INSERT INTO settings_group (name_uz, name_cyrillic, name_ru, order_number)
SELECT 'Ombor va logistika', 'Омбор ва логистика', 'Склад и логистика', 1
WHERE NOT EXISTS (SELECT 1 FROM settings_group WHERE order_number = 1);

INSERT INTO settings_group (name_uz, name_cyrillic, name_ru, order_number)
SELECT 'Moliya', 'Молия', 'Финансы', 2
WHERE NOT EXISTS (SELECT 1 FROM settings_group WHERE order_number = 2);

INSERT INTO settings_group (name_uz, name_cyrillic, name_ru, order_number)
SELECT 'Integratsiyalar', 'Интеграциялар', 'Интеграции', 3
WHERE NOT EXISTS (SELECT 1 FROM settings_group WHERE order_number = 3);

INSERT INTO settings_group (name_uz, name_cyrillic, name_ru, order_number)
SELECT 'Sotuvlar', 'Сотувлар', 'Продажи', 4
WHERE NOT EXISTS (SELECT 1 FROM settings_group WHERE order_number = 4);

UPDATE generic_settings SET settings_group_id = (SELECT id FROM settings_group WHERE order_number = 1) WHERE settings_group_id IS NULL AND settings_type IN ('SORTING_PRODUCTS', 'WORK_WITH_MARKS', 'WORK_WITH_EXPEDITOR', 'WORK_WITH_RESERVATION', 'EXPIRATION_DATE_CONTROL');
UPDATE generic_settings SET settings_group_id = (SELECT id FROM settings_group WHERE order_number = 2) WHERE settings_group_id IS NULL AND settings_type IN ('WORK_WITH_CASHIER', 'E_DOCUMENTS', 'CURRENCY_TYPE', 'ONLINE_KKM');
UPDATE generic_settings SET settings_group_id = (SELECT id FROM settings_group WHERE order_number = 3) WHERE settings_group_id IS NULL AND settings_type IN ('ONE_C_SYNC_ENABLED', 'ONE_C_ENABLED', 'ALLOW_INVOICE_SYNC', 'XTRACE_ENABLED');
UPDATE generic_settings SET settings_group_id = (SELECT id FROM settings_group WHERE order_number = 4) WHERE settings_group_id IS NULL AND settings_type IN ('HAS_CONTRACT', 'IN_MARKETPLACE', 'WORK_WITH_AGENT', 'APPROVE_ORDER_BY_AGENT', 'CUSTOMER_SETTINGS', 'ROLE_SUPERVISOR');
